mapper.insert:
INSERT INTO agent_debug_step (
    run_id, step_order, step_type, agent_name, input_json, output_json, usage_json, error_message
)
VALUES (
    #{runId}, #{stepOrder}, #{stepType}, #{agentName}, #{inputJson}, #{outputJson}, #{usageJson}, #{errorMessage}
)

INSERT INTO agent_prompt_snapshot (
    run_id, prompt_key, prompt_version, prompt_hash, agent_name, model,
    system_prompt, developer_prompt, user_prompt, variables_json
)
VALUES (
    #{runId}, #{promptKey}, #{promptVersion}, #{promptHash}, #{agentName}, #{model},
    #{systemPrompt}, #{developerPrompt}, #{userPrompt}, #{variablesJson}
)

mapper.sql:
WHERE 1 = 1
  AND status = #{status}
  AND intent = #{intent}
  AND target_agent = #{targetAgent}
  AND model = #{model}
  AND user_id = #{userId}
  AND conversation_id = #{conversationId}
  AND created_at >= #{createdFrom}
  AND created_at <= #{createdTo}

WHERE 1 = 1
  AND prompt_key = #{promptKey}
  AND prompt_hash = #{promptHash}
  AND agent_name = #{agentName}
  AND model = #{model}
  AND created_at >= #{createdFrom}
  AND created_at <= #{createdTo}
